import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        try (DataOutputStream out = new DataOutputStream(new FileOutputStream("produk.dat"))) {
            out.writeInt(2);              // jumlah produk
            out.writeUTF("Kopi");
            out.writeInt(15000);
            out.writeUTF("Teh");
            out.writeInt(8000);
        }
        System.out.println("Ukuran: " + new File("produk.dat").length() + " byte");

        try (DataInputStream in = new DataInputStream(new FileInputStream("produk.dat"))) {
            int n = in.readInt();
            for (int i = 0; i < n; i++) {
                System.out.println(in.readUTF() + " " + in.readInt());
            }
        }
    }
}
```

