import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        try (DataOutputStream out = new DataOutputStream(new FileOutputStream("menu.dat"))) {
            out.writeInt(n);
            for (int i = 0; i < n; i++) {
                out.writeUTF(in.next());
                out.writeInt(in.nextInt());
            }
        }
        int total = 0;
        try (DataInputStream d = new DataInputStream(new FileInputStream("menu.dat"))) {
            int m = d.readInt();
            for (int i = 0; i < m; i++) {
                String nama = d.readUTF();
                int harga = d.readInt();
                total += harga;
                System.out.println(nama + ": " + harga);
            }
        }
        System.out.println("Total: " + total);
    }
}
